import fs from "node:fs"
import path from "node:path"
import { PrismaClient } from "@prisma/client"

// tsx does not auto-load .env (only `next start` does) and dotenv isn't a dependency, so
// parse the app's prod .env here — BEFORE constructing the client. Imports are hoisted but
// the client is only instantiated at `new PrismaClient()` below, which runs after this.
function loadEnv(file: string) {
  if (!fs.existsSync(file)) return
  for (const raw of fs.readFileSync(file, "utf8").split("\n")) {
    let line = raw.trim()
    if (!line || line.startsWith("#")) continue
    if (line.startsWith("export ")) line = line.slice(7).trim()
    const eq = line.indexOf("=")
    if (eq === -1) continue
    const key = line.slice(0, eq).trim()
    let val = line.slice(eq + 1).trim()
    if ((val.startsWith('"') && val.endsWith('"')) || (val.startsWith("'") && val.endsWith("'"))) {
      val = val.slice(1, -1)
    }
    if (!(key in process.env)) process.env[key] = val
  }
}
loadEnv(path.join(__dirname, "..", ".env"))

