async function main() {
  for (const post of POSTS) {
    await prisma.blogPost.upsert({
      where: { slug: post.slug },
      create: {
        slug: post.slug,
        status: "PUBLISHED",
        title: post.title,
        description: post.description,
        body: post.body,
        authorName: post.authorName,
        tags: post.tags,
        publishedAt: post.publishedAt
      },
      update: {
        // Refresh content on re-run for these SEO pages (admin hasn't hand-edited them),
        // but never flip status so an archived/unpublished post stays that way.
        title: post.title,
        description: post.description,
        body: post.body,
        tags: post.tags
      }
    })
    console.log(`✓ ${post.slug}`)
  }
  console.log(`Seeded ${POSTS.length} launch posts.`)
}

main()
  .catch((e) => { console.error(e); process.exit(1) })
  .finally(() => prisma.$disconnect())
